local defaults = require("UserConfigs/defaults")
local mainMod = defaults.main_mod
local scriptsDir = defaults.scripts_dir
local UserConfigs = defaults.user_configs_dir
local UserScripts = defaults.user_scripts_dir

-- settings for User defaults apps - set your default terminal and file manager on this file
-- Shared application defaults are provided by UserConfigs/defaults.lua.

--### STANDAR ####
-- Common shortcuts
--bindr = $mainMod, $mainMod_L, exec, pkill rofi || rofi -show drun -modi drun,filebrowser,run,window # Super Key to Launch rofi menu
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd("pkill rofi || true && rofi -show drun -modi drun, filebrowser, run, window"), { description = "app launcher" })
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("xdg-open \"https://\""), { description = "open default browser" })
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd(scriptsDir .. "/OverviewToggle.sh"), { description = "desktop overview" })
--bindd = $mainMod, A, ags overview, exec, pkill rofi || true && ags -t 'overview' # desktop overview (if installed)
--bindd = $mainMod, A, Quickshell overview, global, quickshell:overviewToggle # desktop overview (if installed)
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(defaults.terminal), { description = "Open terminal" })
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(defaults.file_manager), { description = "file manager" })

-- FEATURES / EXTRAS
