-- Cycle windows consistently across the built-in layouts. Runtime bind mutation
-- via `hyprctl keyword` is unavailable when the config provider is Lua.
hl.bind(mainMod .. " + J", hl.dsp.window.cycle_next({ next = true }), { description = "cycle next window" })
hl.bind(mainMod .. " + K", hl.dsp.window.cycle_next({ next = false }), { description = "cycle previous window" })
